CREATE TABLE IF NOT EXISTS articles(id TEXT PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,summary TEXT NOT NULL,body TEXT NOT NULL,section TEXT NOT NULL,lang TEXT NOT NULL CHECK(lang IN ('ar','en')),image TEXT,published_at TEXT NOT NULL,updated_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'published',verified INTEGER NOT NULL DEFAULT 0);CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,visitor TEXT NOT NULL,type TEXT NOT NULL,meta TEXT,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS idx_articles_lang_section ON articles(lang,section);CREATE INDEX IF NOT EXISTS idx_events_created ON events(created_at);